/**
 * Item content (H, 2026-11-25): the collection beyond the launch set. Data only — validation, prices
 * and loadouts live in catalog.ts. Ids are permanent (never rename or reuse; retire instead).
 *
 * Every look is generated by this project's own code (canvas dice faces in src/dice3d/face-paint.ts,
 * CSS boards / bubbles / nickname effects / frames in src/items-content.css, synthesized sounds, DOM
 * particles) or is a standard Unicode emoji: no images, music or characters of unclear rights.
 * Upgrades change looks only (Lv.1 base → Lv.2 better look or motion → Lv.3 special effect, sometimes
 * a sound); nothing changes dice, physics, strategy or the result of a match.
 */
import type { TierId } from "./config";
import type { DiceLook } from "../../dice3d/dice-look";

export type FxShape = "confetti" | "star" | "heart" | "bubble" | "petal" | "snow" | "leaf" | "note" | "spark" | "coin" | "bolt" | "ribbon" | "galaxy" | "rainbow";
export type FxSound = "sparkle" | "coin" | "bell" | "whoosh" | "fanfare";
/** A special effect (win / yacht moment): DOM particles, colours, and an optional Lv.3 sound. */
export type FxLook = { shape: FxShape; colors: string[]; sound?: FxSound };

export type ContentLook = {
  dice?: DiceLook;
  board?: string;
  text?: string;
  css?: string;
  fx?: FxLook;
};
export type ContentItem = {
  id: string;
  category: "dice" | "board" | "bubble" | "profile" | "nameFx" | "fx" | "title";
  tier: TierId;
  name: string;
  acquisition: "coins" | "gems" | "either";
  maxLevel?: 1 | 2 | 3;
  levels?: string[];
  look: ContentLook;
  /** Overrides for Lv.2 and Lv.3 (merged over the Lv.1 look). */
  levelLooks?: Partial<ContentLook>[];
  /** Design family, for browsing (파스텔, 보석, 금속, 대리석, 나무, …). */
  family?: string;
  /** Catalog revision that introduced the item (absent = launch catalog). A server that reports an older
   * revision cannot sell it yet, so the shop shows it as "준비 중" instead of a failing purchase. */
  rev?: number;
  /** Not in the random draw pools (shop only): adding items to a pool would change the odds of the
   * items already in it, which is an economy decision left to the owner (docs/context/COLLECTIONS-2026-11-27.md). */
  drawExcluded?: true;
};

const D = (id: string, tier: TierId, name: string, family: string, look: DiceLook, opts: Partial<ContentItem> = {}): ContentItem => ({ id: "dice." + id, category: "dice", tier, name, family, acquisition: "either", look: { dice: look }, ...opts });
/** Upgradable dice: Lv.2 adds a glow, Lv.3 animates it. */
const DICE_LEVELS = ["기본 외형", "은은한 발광", "움직이는 빛"];
const glowUp = (glow: string, anim: DiceLook["anim"] = "pulse"): Pick<ContentItem, "maxLevel" | "levels" | "levelLooks"> => ({ maxLevel: 3, levels: DICE_LEVELS, levelLooks: [{ dice: { glow } as DiceLook }, { dice: { glow, anim } as DiceLook }] });

